#include <stdio.h>
#include <ctype.h>

int main(void)
{
    const char text[] = "CSE212!";
    int letters = 0, digits = 0;
    for (size_t i = 0; text[i] != '\0'; i++) {
        unsigned char ch = (unsigned char)text[i];
        letters += isalpha(ch) != 0;
        digits += isdigit(ch) != 0;
    }
    printf("letters=%d digits=%d\n", letters, digits);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    printf("tab=%d upper=%d digit=%d\n",
           isspace((unsigned char)'\t') != 0,
           isupper((unsigned char)'A') != 0,
           isdigit((unsigned char)'A') != 0);
    return 0;
}

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    char text[] = "Lab-204";
    for (size_t i = 0; text[i] != '\0'; i++) {
        putchar(toupper((unsigned char)text[i]));
    }
    putchar('\n');
    for (size_t i = 0; text[i] != '\0'; i++) {
        putchar(tolower((unsigned char)text[i]));
    }
    putchar('\n');
    return 0;
}

